"use client";

import * as React from "react";
import type { DonutConfig } from "./donut-frames";
import { acquireBake, releaseBake, frameString } from "./donut-cache";

export interface DonutProps {
  width?: number;
  height?: number;
  R?: number;
  r?: number;
  /** Projection scale. Omit to auto-fit the torus to the grid (recommended). */
  K?: number;
  D?: number;
  /** Optional override for the adaptive u-sampling step (radians). */
  du?: number;
  /** Optional override for the adaptive v-sampling step (radians). */
  dv?: number;
  luminanceChars?: string;
  lightDirection?: [number, number, number];
  speed?: number;
  yScaleOverride?: number;
  className?: string;
  /** CSS background applied to the root element. Transparent by default. */
  background?: string;
  /**
   * Apply CSS `contain` to isolate the per-frame repaint (faster). Default true.
   * Set false when wrapping the donut in an effect that relies on inherited paint
   * — e.g. `<Chrome>`'s `background-clip: text` foil, which an isolated paint
   * context would knock out.
   */
  isolate?: boolean;
}

export function Donut({
  width = 60,
  height = 30,
  R = 0.4,
  r = 0.25,
  K,
  D = 4,
  du,
  dv,
  luminanceChars = " ,-~:;=!*#$@",
  lightDirection = [0, 1, -1],
  speed = 0.5625,
  yScaleOverride,
  className = "font-mono text-xs leading-[1] whitespace-pre cursor-default select-none",
  background,
  isolate = true,
}: DonutProps) {
  const preRef = React.useRef<HTMLPreElement | null>(null);

  const lx = lightDirection[0];
  const ly = lightDirection[1];
  const lz = lightDirection[2];

  React.useEffect(() => {
    const pre = preRef.current;
    if (!pre) return;
    let rafId = 0;
    let terminated = false;

    // Measure the char-cell aspect once, here (fonts are loaded by now), so the
    // bake runs a single time per mount instead of twice (initial guess + remeasure).
    let yScale = yScaleOverride ?? 0.55;
    if (yScaleOverride == null) {
      const probe = document.createElement("span");
      probe.textContent = "0";
      probe.style.position = "absolute";
      probe.style.visibility = "hidden";
      pre.appendChild(probe);
      const charWidth = probe.getBoundingClientRect().width || 1;
      let lineHeight = parseFloat(getComputedStyle(pre).lineHeight);
      if (!isFinite(lineHeight) || lineHeight <= 0) {
        const twoLines = document.createElement("div");
        twoLines.style.position = "absolute";
        twoLines.style.visibility = "hidden";
        twoLines.style.whiteSpace = "pre";
        twoLines.textContent = "0\n0";
        pre.appendChild(twoLines);
        lineHeight = twoLines.getBoundingClientRect().height / 2 || 1;
        pre.removeChild(twoLines);
      }
      pre.removeChild(probe);
      yScale = charWidth / lineHeight;
    }

    // Device tier feeds sampling density (coarser on weak hardware).
    const cores = navigator.hardwareConcurrency || 2;
    const memory = (navigator as unknown as { deviceMemory?: number }).deviceMemory ?? 8;
    const isLowEnd = cores <= 4 || memory <= 4;

    const lMag = Math.hypot(lx, ly, lz) || 1;
    const chars = luminanceChars.length ? luminanceChars : " ";

    // Auto-fit the projection scale to the char grid so the torus always sits
    // inside its bounds with margin, at any width/height. A fixed K overflows
    // small grids (the donut gets clipped). Caller can still override K.
    const Keff =
      K ??
      0.82 * Math.min((width * D) / (2 * (R + r)), (height * D) / (2 * (R + r) * yScale));

    const cfg: DonutConfig = {
      width,
      height,
      R,
      r,
      K: Keff,
      D,
      du,
      dv,
      Lx: lx / lMag,
      Ly: ly / lMag,
      Lz: lz / lMag,
      chars,
      speed,
      yScale,
      isLowEnd,
    };

    // Shared across every Donut with this exact config: one precomputed frame
    // array, one bake, one worker. Identical donuts iterate the same strings.
    const handle = acquireBake(cfg);
    const N = handle.N;

    // Paint one frame now, before the first rAF, so the element is never
    // empty. The bake — worker or main-thread — takes hundreds of milliseconds
    // to land, and the loop below deliberately waits for it, so without this
    // the <pre> has no content for that whole window: a donut placed inside an
    // entrance animation fades in as an empty box and the art appears
    // afterwards at full opacity, as a pop. One frame computed here is cheap
    // and happens once per mount.
    pre.textContent = frameString(handle, 0);

    const frameBudget = isLowEnd ? 33 : 0; // ~30fps on low-end, vsync otherwise
    let lastFrameTime = 0;
    let fi = 0;

    function frame(now: number) {
      if (frameBudget > 0 && now - lastFrameTime < frameBudget) {
        rafId = requestAnimationFrame(frame);
        return;
      }
      // Play ONLY precomputed frames. Computing a frame live during playback
      // is what makes the spin stutter while the bake is still landing (or if
      // the worker never loads). If the next frame isn't baked yet, hold —
      // the element keeps showing the frame above, so the donut is *still*
      // before it spins rather than absent before it appears. Once baked,
      // steady-state is a pure array read with zero math.
      const s = handle.frames[fi];
      if (s === undefined) {
        rafId = requestAnimationFrame(frame);
        return;
      }
      lastFrameTime = now;

      if (!terminated && pre) pre.textContent = s;
      fi = (fi + 1) % N;

      rafId = requestAnimationFrame(frame);
    }

    rafId = requestAnimationFrame(frame);
    return () => {
      terminated = true;
      cancelAnimationFrame(rafId);
      releaseBake(handle);
    };
  }, [width, height, R, r, K, D, du, dv, luminanceChars, speed, lx, ly, lz, yScaleOverride]);

  return (
    <pre
      ref={preRef}
      className={className}
      style={{ background, contain: isolate ? "layout paint style" : undefined }}
      aria-label="ascii donut"
    />
  );
}

// Pure ASCII-donut frame math — no DOM access, so it is safe to import in a Web
// Worker as well as on the main thread. The component uses it for the brief live
// fallback; the worker uses it to bake the whole spin in the background.
//
// Sampling density is derived from each ring's projected circumference (fills
// gaps, no fixed du/dv over/under-sampling); the rotation is expanded so each
// coord is A + B*cv + C*sv and luminance collapses to cv*lumC + sv*lumS (no
// per-pixel normal vector or Math.hypot). The spin loops seamlessly after
// exactly PERIOD_X ax-turns / PERIOD_Z az-turns, so N frames cover one cycle.

export type DonutConfig = {
  width: number;
  height: number;
  R: number;
  r: number;
  K: number;
  D: number;
  du?: number;
  dv?: number;
  Lx: number; // pre-normalised light direction
  Ly: number;
  Lz: number;
  chars: string; // luminance ramp, chars[0] must be the empty/space cell
  speed: number;
  yScale: number; // measured char-cell aspect (charWidth / lineHeight)
  isLowEnd: boolean;
};

export type DonutRenderer = {
  N: number; // frames in one seamless loop
  width: number;
  height: number;
  bufSize: number; // width * height
  chars: string;
  /** Render frame `fi` as char-ramp indices into `out[outOffset .. +bufSize]`. */
  renderToIndices(fi: number, out: Uint8Array, outOffset?: number): void;
  /** Render frame `fi` straight to a printable string. */
  renderString(fi: number): string;
};

/** Convert a frame's index slice into the printable `<pre>` string. */
export function indicesToString(
  out: Uint8Array,
  off: number,
  width: number,
  height: number,
  chars: string,
): string {
  let s = "";
  for (let y = 0; y < height; y++) {
    const start = off + y * width;
    for (let x = 0; x < width; x++) s += chars[out[start + x]!] ?? " ";
    if (y < height - 1) s += "\n";
  }
  return s;
}

export function makeDonutRenderer(cfg: DonutConfig): DonutRenderer {
  const { width, height, R, r, K, D, du, dv, Lx, Ly, Lz, chars, speed, yScale, isLowEnd } = cfg;
  const TWO_PI = Math.PI * 2;

  // --- sampling density (projected-circumference driven) ---
  const oozNear = 1 / Math.max(D - r, 0.0001);
  const oversample = 1.5;
  let uSteps = Math.ceil(TWO_PI * (R + r) * K * oozNear * oversample);
  let vSteps = Math.ceil(TWO_PI * r * K * oozNear * oversample);
  if (du && du > 0) uSteps = Math.ceil(TWO_PI / du);
  if (dv && dv > 0) vSteps = Math.ceil(TWO_PI / dv);
  uSteps = Math.min(2048, Math.max(48, uSteps));
  vSteps = Math.min(2048, Math.max(48, vSteps));
  const MAX_SAMPLES = 96000;
  if (uSteps * vSteps > MAX_SAMPLES) {
    const k = Math.sqrt(MAX_SAMPLES / (uSteps * vSteps));
    uSteps = Math.max(48, Math.ceil(uSteps * k));
    vSteps = Math.max(48, Math.ceil(vSteps * k));
  }
  if (isLowEnd) {
    uSteps = Math.max(48, Math.ceil(uSteps * 0.6));
    vSteps = Math.max(48, Math.ceil(vSteps * 0.6));
  }
  const adu = TWO_PI / uSteps;
  const adv = TWO_PI / vSteps;

  // --- seamless loop length: exactly PERIOD_X ax-turns / PERIOD_Z az-turns ---
  const PERIOD_X = 5,
    PERIOD_Z = 3;
  const baseAxInc = 0.025 * speed;
  let N = Math.round((TWO_PI * PERIOD_X) / baseAxInc);
  if (!isFinite(N) || N < 1) N = 1;
  const axInc = (TWO_PI * PERIOD_X) / N;
  const azInc = (TWO_PI * PERIOD_Z) / N;

  const cx = width >> 1;
  const cy = height >> 1;
  const Ky = K * yScale;
  const cmax = chars.length - 1;
  const bufSize = width * height;

  const zbuf = new Float32Array(bufSize);
  const cosU = new Float32Array(uSteps);
  const sinU = new Float32Array(uSteps);
  const cosV = new Float32Array(vSteps);
  const sinV = new Float32Array(vSteps);
  for (let i = 0; i < uSteps; i++) {
    const u = i * adu;
    cosU[i] = Math.cos(u);
    sinU[i] = Math.sin(u);
  }
  for (let i = 0; i < vSteps; i++) {
    const v = i * adv;
    cosV[i] = Math.cos(v);
    sinV[i] = Math.sin(v);
  }
  const scratch = new Uint8Array(bufSize);

  function renderToIndices(fi: number, out: Uint8Array, outOffset = 0): void {
    const ax = fi * axInc;
    const az = fi * azInc;
    out.fill(0, outOffset, outOffset + bufSize);
    zbuf.fill(-Infinity);

    const cosAx = Math.cos(ax),
      sinAx = Math.sin(ax);
    const cosAz = Math.cos(az),
      sinAz = Math.sin(az);
    const cosAxSinAz = cosAx * sinAz;
    const cosAxCosAz = cosAx * cosAz;
    const Cpx = r * sinAx * sinAz;
    const Cpy = -r * sinAx * cosAz;
    const Cz = r * cosAx;
    const lumS = sinAx * sinAz * Lx - sinAx * cosAz * Ly + cosAx * Lz;

    for (let ui = 0; ui < uSteps; ui++) {
      const cu = cosU[ui]!,
        su = sinU[ui]!;
      const k1 = cu * cosAz - su * cosAxSinAz;
      const k2 = cu * sinAz + su * cosAxCosAz;
      const ss = su * sinAx;
      const Apx = R * k1,
        Bpx = r * k1;
      const Apy = R * k2,
        Bpy = r * k2;
      const Az = R * ss + D,
        Bz = r * ss;
      const lumC = k1 * Lx + k2 * Ly + ss * Lz;

      for (let vi = 0; vi < vSteps; vi++) {
        const cv = cosV[vi]!,
          sv = sinV[vi]!;
        const z = Az + Bz * cv + Cz * sv;
        if (z <= 0) continue;
        const ooz = 1 / z;
        const px2 = Apx + Bpx * cv + Cpx * sv;
        const py2 = Apy + Bpy * cv + Cpy * sv;
        const xProj = (cx + K * px2 * ooz) | 0;
        const yProj = (cy - Ky * py2 * ooz) | 0;
        if (xProj >= 0 && xProj < width && yProj >= 0 && yProj < height) {
          const idx = xProj + yProj * width;
          if (ooz > zbuf[idx]!) {
            zbuf[idx] = ooz;
            const lum = cv * lumC + sv * lumS;
            if (lum > 0) out[outOffset + idx] = Math.min(cmax, (lum * cmax) | 0);
          }
        }
      }
    }
  }

  function renderString(fi: number): string {
    renderToIndices(fi, scratch, 0);
    return indicesToString(scratch, 0, width, height, chars);
  }

  return { N, width, height, bufSize, chars, renderToIndices, renderString };
}

// Shared bake registry for <Donut/>. Every Donut with an identical config shares
// ONE entry: one precomputed array of frame strings, baked once. Steady-state
// animation is then literally `pre.textContent = frames[i]` — pure array
// iteration, zero per-frame math.
//
// The array is filled by whichever finishes first:
//   - a single process-wide web worker (off-thread, preferred), or
//   - a chunked main-thread bake (fallback) that fills it over a few idle slices.
// The main-thread fallback ALSO fires if the worker is present but never answers
// (broken/blocked in some bundlers), so playback always converges to smooth
// array iteration within ~1s regardless of environment. N donuts on a page never
// spawn N workers or recompute the same frame twice.
import { makeDonutRenderer, type DonutConfig } from "./donut-frames";
import type { BakeRequest, BakeResult } from "./donut.worker";

export interface DonutHandle {
  key: string;
  cfg: DonutConfig;
  N: number;
  live: ReturnType<typeof makeDonutRenderer>;
  /** Precomputed frame strings, shared across every instance. Filled lazily/by bake. */
  frames: (string | undefined)[];
  /** True once every frame string is materialised — pure array iteration from here. */
  ready: boolean;
  bakeStarted: boolean;
  refs: number;
  /** Set once the entry is evicted — stops any in-flight bake from resuming. */
  cancelled: boolean;
  /** Pending main-thread chunk handle (rIC id or timeout id), if any. */
  bakeHandle: number | null;
  /** Worker-answer safety-net timeout id, if any. */
  fallbackTimer: ReturnType<typeof setTimeout> | null;
}

const handles = new Map<string, DonutHandle>();

// --- one process-wide worker, created lazily, with graceful fallback ----------
let worker: Worker | null = null;
let workerTried = false;

function ensureWorker(): void {
  if (workerTried) return;
  workerTried = true;
  if (typeof Worker === "undefined") return;
  try {
    worker = new Worker(new URL("./donut.worker.ts", import.meta.url), { type: "module" });
    worker.onmessage = (e: MessageEvent<BakeResult>) => fillFromStrings(e.data.key, e.data.frames);
    // A worker that fails to load just leaves entries to the main-thread bake.
    worker.onerror = () => {
      worker = null;
    };
  } catch {
    worker = null;
  }
}

/**
 * Terminate the shared worker once no bakes reference it. `workerTried` is reset
 * so the next bake request lazily recreates it via ensureWorker().
 */
function teardownWorker(): void {
  if (worker) worker.terminate();
  worker = null;
  workerTried = false;
}

function cancelMainThreadBake(h: DonutHandle): void {
  if (h.bakeHandle === null) return;
  if (typeof cancelIdleCallback !== "undefined") cancelIdleCallback(h.bakeHandle);
  else clearTimeout(h.bakeHandle);
  h.bakeHandle = null;
}

function round(n: number): number {
  return Math.round(n * 1000) / 1000;
}

function keyOf(cfg: DonutConfig): string {
  return [
    cfg.width,
    cfg.height,
    round(cfg.R),
    round(cfg.r),
    round(cfg.K),
    round(cfg.D),
    cfg.du ?? 0,
    cfg.dv ?? 0,
    round(cfg.Lx),
    round(cfg.Ly),
    round(cfg.Lz),
    cfg.chars,
    round(cfg.speed),
    round(cfg.yScale),
    cfg.isLowEnd ? 1 : 0,
  ].join("|");
}

/** Worker delivered the finished frame strings — adopt them wholesale (zero per-frame work). */
function fillFromStrings(key: string, frames: string[]): void {
  const h = handles.get(key);
  if (!h || h.ready) return;
  for (let fi = 0; fi < h.N; fi++) {
    const s = frames[fi];
    if (s !== undefined) h.frames[fi] = s;
  }
  h.ready = true;
}

/** Fallback: bake the loop on the main thread, spread across idle slices (non-blocking). */
function mainThreadBake(h: DonutHandle): void {
  if (h.ready || h.cancelled) return;
  const CHUNK = 48;
  let fi = 0;
  const schedule: (cb: () => void) => number =
    typeof requestIdleCallback !== "undefined"
      ? (cb) => requestIdleCallback(() => cb())
      : (cb) => setTimeout(cb, 0) as unknown as number;
  function step(): void {
    h.bakeHandle = null;
    if (h.ready || h.cancelled) return; // worker beat us to it, or evicted
    const end = Math.min(h.N, fi + CHUNK);
    for (; fi < end; fi++) {
      if (h.frames[fi] === undefined) h.frames[fi] = h.live.renderString(fi);
    }
    if (fi < h.N) h.bakeHandle = schedule(step);
    else h.ready = true;
  }
  h.bakeHandle = schedule(step);
}

function scheduleBake(h: DonutHandle): void {
  if (h.bakeStarted) return;
  h.bakeStarted = true;
  ensureWorker();
  if (worker) {
    worker.postMessage({ key: h.key, cfg: h.cfg } satisfies BakeRequest);
    // Safety net: if the worker never answers, fall back to a main-thread bake.
    h.fallbackTimer = setTimeout(() => {
      h.fallbackTimer = null;
      if (!h.ready && !h.cancelled) mainThreadBake(h);
    }, 1000);
  } else {
    mainThreadBake(h);
  }
}

/** Get (creating if needed) the shared bake for this config and bump its refcount. */
export function acquireBake(cfg: DonutConfig): DonutHandle {
  const key = keyOf(cfg);
  let h = handles.get(key);
  if (!h) {
    const live = makeDonutRenderer(cfg);
    h = {
      key,
      cfg,
      N: live.N,
      live,
      frames: new Array(live.N),
      ready: false,
      bakeStarted: false,
      refs: 0,
      cancelled: false,
      bakeHandle: null,
      fallbackTimer: null,
    };
    handles.set(key, h);
    scheduleBake(h);
  }
  h.refs++;
  return h;
}

/**
 * Drop a reference. When a bake's refs reach 0 its entry (and its frames) are
 * evicted from the cache and any in-flight main-thread bake / fallback timer is
 * cancelled. Once no bakes remain, the shared worker is terminated (and lazily
 * recreated on the next bake request). Bakes still referenced are untouched, so
 * "multiple donuts share one bake" is preserved.
 */
export function releaseBake(h: DonutHandle): void {
  h.refs = Math.max(0, h.refs - 1);
  if (h.refs > 0) return;

  // Evict: stop any pending work and free the entry + its frame strings.
  h.cancelled = true;
  cancelMainThreadBake(h);
  if (h.fallbackTimer !== null) {
    clearTimeout(h.fallbackTimer);
    h.fallbackTimer = null;
  }
  h.frames.length = 0;
  // Only delete the live entry (a remount may have already replaced it).
  if (handles.get(h.key) === h) handles.delete(h.key);

  if (handles.size === 0) teardownWorker();
}

/**
 * The printable `<pre>` string for frame `fi`. Once baked this is a plain array
 * read; before the bake lands it computes (and shares) the frame on demand so the
 * same frame is never rendered twice across instances.
 */
export function frameString(h: DonutHandle, fi: number): string {
  const cached = h.frames[fi];
  if (cached !== undefined) return cached;
  const s = h.live.renderString(fi);
  h.frames[fi] = s;
  return s;
}

// Background donut baker. Receives `{ key, cfg }`, renders every frame of one
// seamless loop straight to its finished `<pre>` string, and posts the `string[]`
// back tagged with `key` so the main thread can route it to the right cache entry.
// Building the finished strings here (not just char-ramp indices) keeps the main
// thread out of the per-frame string concatenation entirely — once a bake lands,
// playback is a pure array swap with no first-loop materialisation jank exactly
// when the page first loads. A single worker bakes every distinct config
// sequentially. The main thread never does this math.
import { makeDonutRenderer, type DonutConfig } from "./donut-frames";

export type BakeRequest = { key: string; cfg: DonutConfig };
export type BakeResult = {
  key: string;
  frames: string[]; // one printable <pre> string per frame, frame-major
};

const ctx = self as unknown as Worker;

ctx.onmessage = (e: MessageEvent<BakeRequest>) => {
  const { key, cfg } = e.data;
  const renderer = makeDonutRenderer(cfg);
  const { N } = renderer;
  const frames: string[] = new Array(N);
  for (let fi = 0; fi < N; fi++) frames[fi] = renderer.renderString(fi);
  ctx.postMessage({ key, frames } satisfies BakeResult);
};
